const http = require('http');

const payload = JSON.stringify({
  json: {
    items: [{ productId: 2, quantity: 1 }]
  }
});

function makeRequest() {
  return new Promise((resolve) => {
    const req = http.request({
      hostname: 'localhost',
      port: 3001,
      path: '/operations/checkout',
      method: 'POST',
      headers: {
        'Content-Type': 'application/json',
        'Content-Length': Buffer.byteLength(payload)
      }
    }, (res) => {
      let data = '';
      res.on('data', (chunk) => { data += chunk; });
      res.on('end', () => {
        resolve({
          statusCode: res.statusCode,
          body: JSON.parse(data)
        });
      });
    });

    req.on('error', (e) => {
      resolve({
        statusCode: 500,
        body: { message: e.message }
      });
    });

    req.write(payload);
    req.end();
  });
}

async function runTest() {
  console.log("Firing 10 concurrent checkout requests for Ergonomic Mechanical Keyboard (Inventory: 1)...");

  const promises = [];
  for (let i = 0; i < 10; i++) {
    promises.push(makeRequest());
  }

  const results = await Promise.all(promises);

  let successCount = 0;
  let failureCount = 0;
  let successDetails = [];
  let failureDetails = [];

  results.forEach((res, index) => {
    if (res.statusCode === 200) {
      successCount++;
      successDetails.push({ index, body: res.body });
    } else {
      failureCount++;
      failureDetails.push({ index, statusCode: res.statusCode, body: res.body });
    }
  });

  console.log("\n--- TEST RESULTS ---");
  console.log(`Total Requests: 10`);
  console.log(`Success Count: ${successCount}`);
  console.log(`Failure Count: ${failureCount}`);

  console.log("\nSuccess Details:");
  console.log(JSON.stringify(successDetails, null, 2));

  console.log("\nSample Failure Details (first 3):");
  console.log(JSON.stringify(failureDetails.slice(0, 3), null, 2));

  if (successCount === 1) {
    console.log("\n? SUCCESS: Exactly one concurrent request succeeded!");
  } else {
    console.log("\n? FAILURE: Expected exactly one request to succeed, but got " + successCount);
  }
}

runTest();

